using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;
using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.Geometry;using Autodesk.AutoCAD.EditorInput;using Autodesk.AutoCAD.ApplicationServices;using App=Autodesk.AutoCAD.ApplicationServices.Core.Application;
public class PaperEntitiesTestsV1 {
 public class Config {public string source,source_sha256,handle,folder,receipt,destination,native_type;public double[] offset;}
 static JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=10000000};
 static void Need(bool b,string m){if(!b)throw new InvalidOperationException(m);}
 static string LayoutName(Database d){using(var t=d.TransactionManager.StartTransaction()){foreach(DBDictionaryEntry row in (DBDictionary)t.GetObject(d.LayoutDictionaryId,OpenMode.ForRead)){var l=(Layout)t.GetObject(row.Value,OpenMode.ForRead);if(!l.ModelType)return l.LayoutName;}}throw new InvalidOperationException("NO_LAYOUT");}
 static object Parts(Entity e,int depth=0){if(e is DBText){var x=(DBText)e;return new{type="text",text=x.TextString,p=new[]{x.Position.X,x.Position.Y,x.Position.Z},height=x.Height,width=x.WidthFactor,rotation=x.Rotation};}if(e is MText){var x=(MText)e;return new{type="mtext",text=x.Contents,p=new[]{x.Location.X,x.Location.Y,x.Location.Z},height=x.TextHeight,rotation=x.Rotation};}if(e is Line||e is Polyline||e is Arc||e is Circle)return NativeGeometryReadV1.Geometry(e,false);Need(depth<5,"DEPTH");var parts=new DBObjectCollection();try{e.Explode(parts);return parts.Cast<DBObject>().OfType<Entity>().Select(x=>Parts(x,depth+1)).ToArray();}finally{foreach(DBObject o in parts)o.Dispose();}}
 static object Shape(Entity e){var g=new GripDataCollection();e.GetGripPoints(g,1,5,Vector3d.ZAxis,GetGripPointsFlags.GripPointsOnly);return new{type=e.GetRXClass().Name,layer=e.Layer,color=e.Color.ToString(),lt=e.Linetype,lw=(int)e.LineWeight,bounds=BoundCadEditsV1.Bounds(e),grips=g.Cast<GripData>().Select(x=>new[]{x.GripPoint.X,x.GripPoint.Y,x.GripPoint.Z}).ToArray(),parts=Parts(e)};}
 static BoundCadEditsV1.Target Frame(Database d,double[] b,string layout=null){using(var t=d.TransactionManager.StartTransaction()){var bt=(BlockTable)t.GetObject(d.BlockTableId,OpenMode.ForWrite);var def=new BlockTableRecord{Name="TEST_GRID_FRAME"};bt.Add(def);t.AddNewlyCreatedDBObject(def,true);var p=new Polyline();p.AddVertexAt(0,new Point2d(0,0),0,0,0);p.AddVertexAt(1,new Point2d(b[2]-b[0],0),0,0,0);p.AddVertexAt(2,new Point2d(b[2]-b[0],b[3]-b[1]),0,0,0);p.AddVertexAt(3,new Point2d(0,b[3]-b[1]),0,0,0);p.Closed=true;def.AppendEntity(p);t.AddNewlyCreatedDBObject(p,true);var ms=(BlockTableRecord)t.GetObject(BoundCadEditsV1.Space(t,d,layout??LayoutName(d)),OpenMode.ForWrite);var f=new BlockReference(new Point3d(b[0],b[1],0),def.ObjectId);ms.AppendEntity(f);t.AddNewlyCreatedDBObject(f,true);var id=BoundCadEditsV1.Identity(f);t.Commit();return id;}}
 [CommandMethod("HLCADPAPERENTITYTESTV10",CommandFlags.Session)] public void Run(){var doc=App.DocumentManager.MdiActiveDocument;var old=HostApplicationServices.WorkingDatabase;var a=doc.Editor.GetString(new PromptStringOptions("\nPaper entity config: "){AllowSpaces=true});if(a.Status!=PromptStatus.OK)return;Config c=null;Document staging=null;
 try{c=J.Deserialize<Config>(File.ReadAllText(a.StringResult.Trim('"')));Need(!File.Exists(c.receipt)&&BoundCadEditsV1.Hash(c.source)==c.source_sha256,"SOURCE_IDENTITY");c.native_type=c.native_type??"TDbSymbCoord";c.offset=c.offset??new[]{100.0,200.0};Need(c.offset.Length==2,"OFFSET_XY_REQUIRED");Directory.CreateDirectory(c.folder);string output=Path.Combine(c.folder,"paper_copy.dwg");Need(!File.Exists(output),"OUTPUT_EXISTS");string expected;List<string> handles=new List<string>();
 string stage=Path.Combine(c.folder,"destination_staging.dwg");File.Copy(c.destination,stage,false);staging=App.DocumentManager.Open(stage,false);App.DocumentManager.MdiActiveDocument=staging;
 using(staging.LockDocument())using(var source=new Database(false,true)){
 source.ReadDwgFile(c.source,FileOpenMode.OpenForReadAndAllShare,true,null);source.CloseInput(true);var dest=staging.Database;HostApplicationServices.WorkingDatabase=source;
 string sourceLayout;using(var tr=source.TransactionManager.StartTransaction()){var e=(Entity)tr.GetObject(source.GetObjectId(false,new Handle(Convert.ToInt64(c.handle,16)),0),OpenMode.ForRead);var btr=(BlockTableRecord)tr.GetObject(e.OwnerId,OpenMode.ForRead);sourceLayout=((Layout)tr.GetObject(btr.LayoutId,OpenMode.ForRead)).LayoutName;}
 BoundCadEditsV1.Target[] targets;double[] box;string[] before;
 using(var t=source.TransactionManager.StartTransaction()){var owner=(BlockTableRecord)t.GetObject(BoundCadEditsV1.Space(t,source,sourceLayout),OpenMode.ForWrite);var coord=(Entity)t.GetObject(source.GetObjectId(false,new Handle(Convert.ToInt64(c.handle,16)),0),OpenMode.ForRead);Need(coord.OwnerId==owner.ObjectId&&coord.GetRXClass().Name==c.native_type,"EXACT_PAPER_NATIVE_TYPE_REQUIRED");box=BoundCadEditsV1.Bounds(coord);box=new[]{box[0]-20,box[1]-20,box[2]+20,box[3]+20};var line=new Line(new Point3d(box[0]+1,box[1]+1,0),new Point3d(box[2]-1,box[1]+1,0));owner.AppendEntity(line);t.AddNewlyCreatedDBObject(line,true);var text=new MText{Location=new Point3d(box[0]+2,box[1]+5,0),TextHeight=1,Contents="1m grid"};owner.AppendEntity(text);t.AddNewlyCreatedDBObject(text,true);var entities=new Entity[]{coord,line,text};targets=entities.Select(BoundCadEditsV1.Identity).ToArray();before=entities.Select(e=>J.Serialize(Shape(e))).ToArray();t.Commit();}
 var sf=Frame(source,box,sourceLayout);using(var tx=source.TransactionManager.StartTransaction()){var es=targets.Select(x=>(Entity)tx.GetObject(source.GetObjectId(false,new Handle(Convert.ToInt64(x.handle,16)),0),OpenMode.ForRead)).ToArray();targets=es.Select(BoundCadEditsV1.Identity).ToArray();before=es.Select(x=>J.Serialize(Shape(x))).ToArray();}HostApplicationServices.WorkingDatabase=dest;var tf=Frame(dest,new[]{box[0]+c.offset[0],box[1]+c.offset[1],box[2]+c.offset[0],box[3]+c.offset[1]});var job=new BoundCadEditsV1.Job{source_layout=sourceLayout,target_layout=LayoutName(dest),source_frame=sf,target_frames=new[]{tf},source_targets=targets};
 bool rejected=false;try{BoundCadEditsV1.ApplyPaperCopies(source,dest,job);}catch(InvalidOperationException){rejected=true;}Need(rejected,"TEXT_ONLY_NOT_PRESERVED");var copied=J.Deserialize<List<Dictionary<string,object>>>(J.Serialize(BoundCadEditsV1.ApplyPaperCopies(source,dest,job,true)));handles=copied.Select(x=>(string)x["target_handle"]).ToList();
 using(var t=dest.TransactionManager.StartTransaction()){var owner=(BlockTableRecord)t.GetObject(BoundCadEditsV1.Space(t,dest,LayoutName(dest)),OpenMode.ForRead);var entities=handles.Select(h=>(Entity)t.GetObject(dest.GetObjectId(false,new Handle(Convert.ToInt64(h,16)),0),OpenMode.ForRead)).ToArray();Need(entities.Length==3,"EXTRA_OBJECTS");for(int i=0;i<3;i++){using(var clone=(Entity)entities[i].Clone()){clone.TransformBy(Matrix3d.Displacement(new Vector3d(-c.offset[0],-c.offset[1],0)));var afterClone=J.Serialize(Shape(clone));if(!CadValueCompareV1.Json(before[i],afterClone)){File.WriteAllText(Path.Combine(c.folder,"clone_difference.json"),J.Serialize(new{index=i,before=J.DeserializeObject(before[i]),after=J.DeserializeObject(afterClone)}));throw new InvalidOperationException("CLONE_CONTENT_CHANGED:"+i);}}}expected=J.Serialize(entities.Select(Shape).ToArray());}dest.SaveAs(output,DwgVersion.AC1032);
 }
 App.DocumentManager.MdiActiveDocument=doc;HostApplicationServices.WorkingDatabase=old;staging.CloseAndDiscard();staging=null;staging=App.DocumentManager.Open(output,true);App.DocumentManager.MdiActiveDocument=staging;using(staging.LockDocument()){var db=staging.Database;HostApplicationServices.WorkingDatabase=db;using(var t=db.TransactionManager.StartTransaction()){var actual=J.Serialize(handles.Select(h=>Shape((Entity)t.GetObject(db.GetObjectId(false,new Handle(Convert.ToInt64(h,16)),0),OpenMode.ForRead))).ToArray());Need(CadValueCompareV1.Json(expected,actual),"REOPEN_CHANGED");}}
 Need(BoundCadEditsV1.Hash(c.source)==c.source_sha256,"SOURCE_CHANGED");File.WriteAllText(c.receipt,J.Serialize(new{status="ISOLATED_PAPER_ENTITIES_SAVE_REOPEN_VERIFIED",types=new[]{c.native_type,"AcDbLine","AcDbMText"},full_document_fixture=true,native_translation_preserved=true,text_only_rejection_preserved=true,source_unchanged=true,output,sha256=BoundCadEditsV1.Hash(output)}));
 }catch(System.Exception e){if(c!=null&&!File.Exists(c.receipt))File.WriteAllText(c.receipt,J.Serialize(new{status="FAIL",error=e.ToString()}));}finally{App.DocumentManager.MdiActiveDocument=doc;HostApplicationServices.WorkingDatabase=old;if(staging!=null)staging.CloseAndDiscard();}
 }
}
